191	// mustOfflineReview runs RecheckDecisionOffline, failing on error.
192	func mustOfflineReview(t *testing.T, recs []AuditRecord, cp Checkpoint, seq int) OfflineDecisionReview {
193		t.Helper()
194		rv, err := RecheckDecisionOffline("acme", recs, cp, seq)
195		if err != nil {
196			t.Fatalf("offline review seq %d: %v", seq, err)
197		}
198		return rv
199	}
