343	// TestEmptyListShapesAndMatchlessDenialsPreserved locks the current
344	// storage shapes for empty lists: a request with no roles (nil) and one
345	// with an explicitly empty role list must not be exchanged for each other
346	// on read, and denials that matched no policy — both the "no matching
347	// allow policy" result (non-nil empty matched list) and an envelope
348	// rejection before policy evaluation (nil matched list, version 0) — must
349	// keep their original result shapes through export, paging and archive.
350	func TestEmptyListShapesAndMatchlessDenialsPreserved(t *testing.T) {
351		s := NewStore()
352		if _, err := s.Publish("acme", 0, nil); err != nil { // v1 denies everything
353			t.Fatal(err)
354		}
355	
356		nilReq := request("acme", "u1", "r1", "org/a", "read") // roles left nil
357		nilDeny := s.Decide("acme", nilReq)                    // seq 2
358		emptyReq := request("acme", "u2", "r1", "org/a", "read")
359		emptyReq.Subject.Roles = []string{}     // explicitly empty
360		emptyDeny := s.Decide("acme", emptyReq) // seq 3
361		disabledReq := request("acme", "u3", "r1", "org/a", "read")
362		disabledReq.Subject.Disabled = true
363		envDeny := s.Decide("acme", disabledReq) // seq 4, envelope rejection
364	
365		for _, d := range []Decision{nilDeny, emptyDeny} {
366			if d.Allowed || d.Reason != "no matching allow policy" || d.Version != 1 || len(d.Matched) != 0 {
367				t.Fatalf("setup policy denial = %+v", d)
368			}
369		}
370		if envDeny.Allowed || envDeny.Reason != "subject is disabled" || envDeny.Version != 0 || envDeny.Matched != nil {
371			t.Fatalf("setup envelope denial = %+v, want nil matched, version 0", envDeny)
372		}
373	
374		// A late edit of the caller's explicitly-empty slice must not matter.
375		emptyReq.Subject.Roles = append(emptyReq.Subject.Roles, "late-role")
376	
377		recs, cp, err := s.AuditExport("acme", 0)
378		if err != nil {
379			t.Fatal(err)
380		}
381		if err := VerifyAudit("acme", recs, cp); err != nil {
382			t.Fatalf("empty-list chain: %v", err)
383		}
384		nilRec := recordBySeq(t, recs, 2)
385		emptyRec := recordBySeq(t, recs, 3)
386		envRec := recordBySeq(t, recs, 4)
387	
388		if nilRec.Decision.Request.Subject.Roles != nil {
389			t.Fatalf("nil roles read back as %v", nilRec.Decision.Request.Subject.Roles)
390		}
391		if roles := emptyRec.Decision.Request.Subject.Roles; roles == nil || len(roles) != 0 {
392			t.Fatalf("explicitly empty roles read back as %v", roles)
393		}
394		// The two shapes must not collapse onto one fingerprint.
395		if nilRec.Fingerprint == emptyRec.Fingerprint {
396			t.Fatal("nil roles and empty roles share a fingerprint")
397		}
398		// Policy-evaluation denials carry a non-nil empty matched list; the
399		// envelope rejection carries a nil one. Both are matchless denials.
400		if nilRec.Decision.Decision.Matched == nil || emptyRec.Decision.Decision.Matched == nil {
401			t.Fatal("no-match denial must keep its non-nil empty matched list")
402		}
403		if envRec.Decision.Decision.Matched != nil {
404			t.Fatal("envelope rejection matched list must stay nil")
405		}
406		if !reflect.DeepEqual(nilRec.Decision.Decision, cloneDecisionValue(nilDeny)) {
407			t.Fatalf("nil-roles denial not preserved: %+v", nilRec.Decision.Decision)
408		}
409		if !reflect.DeepEqual(emptyRec.Decision.Decision, cloneDecisionValue(emptyDeny)) {
410			t.Fatalf("empty-roles denial not preserved: %+v", emptyRec.Decision.Decision)
411		}
412	
413		// The paged query keeps the same shapes.
414		paged := drainAudit(t, s, "acme", AuditDecision, "")
415		if got := recordBySeq(t, paged, 2).Decision.Request.Subject.Roles; got != nil {
416			t.Fatalf("paged query turned nil roles into %v", got)
417		}
418		if got := recordBySeq(t, paged, 3).Decision.Request.Subject.Roles; got == nil || len(got) != 0 {
419			t.Fatalf("paged query turned empty roles into %v", got)
420		}
421	
422		// The archive round trip keeps the same shapes and still verifies.
423		archive, err := EncodeAuditArchive("acme", recs, cp)
424		if err != nil {
425			t.Fatal(err)
426		}
427		decoded, err := DecodeAuditArchive(archive, "acme", cp)
428		if err != nil {
429			t.Fatalf("archive decode: %v", err)
430		}
431		if !reflect.DeepEqual(decoded, recs) {
432			t.Fatal("archive round trip changed empty-list shapes")
433		}
434		if err := VerifyAudit("acme", decoded, cp); err != nil {
435			t.Fatalf("decoded empty-list chain: %v", err)
436		}
437	
438		// Every matchless denial re-reviews to the original conclusion.
439		for seq, want := range map[int]Decision{2: nilDeny, 3: emptyDeny, 4: envDeny} {
440			if got, err := s.RecheckDecision("acme", seq); err != nil || !decisionsEqual(got, want) {
441				t.Fatalf("online recheck seq %d = %+v, %v, want %+v", seq, got, err, want)
442			}
443			if rv := mustOfflineReview(t, recs, cp, seq); !rv.Consistent {
444				t.Fatalf("matchless denial seq %d review inconsistent: %+v", seq, rv)
445			}
446		}
447	}
