package darksafe

import (
	"encoding/hex"
	"os"
	"testing"
)

func TestDumpListEncodingForDiff(t *testing.T) {
	mk := func(roles, matched []string, policies []Policy, raw string) []AuditRecord {
		recs, _, err := syntheticChain("acme", []func(int) (string, *PolicyChange, *DecisionRecord){
			func(int) (string, *PolicyChange, *DecisionRecord) {
				return AuditPolicyChange, &PolicyChange{Version: 1, Policies: policies,
					SourceVersion: 0, RolledBack: false}, nil
			},
			func(int) (string, *PolicyChange, *DecisionRecord) {
				r := request("acme", "u1", "r1", "org/a", "read")
				r.Subject.Roles = roles
				return AuditDecision, nil, &DecisionRecord{
					Request:  r,
					Decision: Decision{Allowed: true, Reason: "原因" + raw, Matched: matched, Version: 1},
				}
			},
		})
		if err != nil {
			t.Fatal(err)
		}
		return recs
	}

	lists := [][]string{nil, {}, {"a"}, {"a", "b", "a"}, {"角色", "  x  ", "原\xff始", "\xfe", "�"}}
	pols := [][]Policy{
		nil,
		{},
		{{ID: "p1", Subject: "s", Action: "read", Scope: "org/a", Effect: EffectAllow}},
	}
	var out []byte
	for _, raw := range []string{"", "\xff", "\xfe", "�"} {
		for _, pol := range pols {
			for _, roles := range lists {
				for _, matched := range lists {
					recs := mk(roles, matched, pol, raw)
					for i := range recs {
						r := &recs[i]
						out = append(out, []byte("canon ")...)
						out = append(out, []byte(hex.EncodeToString(encodeCanonical(r)))...)
						out = append(out, '\n')
						out = append(out, []byte("json  ")...)
						out = append(out, []byte(hex.EncodeToString(encodeJSONEnvelope(r)))...)
						out = append(out, '\n')
						out = append(out, []byte("fp    "+fingerprintFor(r)+"\n")...)
					}
					_, cp, err := func() (string, Checkpoint, error) {
						cp := Checkpoint{Org: "acme", EndSeq: len(recs), Fingerprint: recs[len(recs)-1].Fingerprint}
						if err := VerifyAudit("acme", recs, cp); err != nil {
							return "", Checkpoint{}, err
						}
						return "", cp, nil
					}()
					if err != nil {
						t.Fatal(err)
					}
					arc, err := EncodeAuditArchive("acme", recs, cp)
					if err != nil {
						t.Fatal(err)
					}
					out = append(out, []byte("arch  "+hex.EncodeToString(arc)+"\n\n")...)
				}
			}
		}
	}
	if err := os.WriteFile("/tmp/list_encoding_dump.txt", out, 0644); err != nil {
		t.Fatal(err)
	}
}

